(()=>{const key='gramin-service-branch',branches=[{id:'narsipatnam',name:'Narsipatnam branch',latitude:17.667,longitude:82.612},{id:'makavarapalem',name:'Makavarapalem branch',latitude:17.427,longitude:82.436},{id:'chodavaram',name:'Chodavaram branch',latitude:17.829,longitude:82.936}],read=()=>{try{const saved=JSON.parse(localStorage.getItem(key)||'null');return branches.find(x=>x.id===saved?.id)||branches[0];}catch{return branches[0];}},save=x=>localStorage.setItem(key,JSON.stringify(x));window.graminLocation={get:read};const update=()=>{const h=document.querySelector('header .location');if(!h)return;if(!localToken||!localUser||role!=='customer'){h.textContent='';return;}const current=read();h.innerHTML=`<label class="branch-picker">Service branch<select id="branch-select">${branches.map(x=>`<option value="${x.id}" ${x.id===current.id?'selected':''}>${x.name}</option>`).join('')}</select><small>Village suggestions within 50 km</small></label>`;document.querySelector('#branch-select').onchange=e=>{save(branches.find(x=>x.id===e.target.value));update();toast('Service branch changed. Village suggestions now use its 50 km area.');};};const baseRender=render;render=function(){baseRender();update();};update();})();
